const {chromium}=require('playwright');
const fs=require('node:fs');
const out='/private/tmp/sirm-desktop-audit';
(async()=>{
 const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true,args:['--enable-precise-memory-info']});
 const context=await browser.newContext({viewport:{width:1440,height:1000}});
 await context.addInitScript(()=>{
  window.audit={parse:[],functions:{},longTasks:[],errors:[]};
  new PerformanceObserver(list=>audit.longTasks.push(...list.getEntries().map(e=>({start:e.startTime,duration:e.duration})))).observe({type:'longtask',buffered:true});
  const parse=JSON.parse;JSON.parse=function(text,...args){const t=performance.now();const value=parse.call(this,text,...args);if(typeof text==='string'&&text.length>100000)audit.parse.push({characters:text.length,ms:performance.now()-t});return value};
  window.addEventListener('error',e=>audit.errors.push(e.message));
  document.addEventListener('DOMContentLoaded',()=>{
   for(const name of ['normalizeDatasetPayload','normalizeCountryRegionRecord','canonicalizePublicDataset','displayDataset','renderRecordsForGeneration','recordMatchesActiveFilters','renderResults','createResultItem','measureMasonryItems','prepareFirstResultViewport']){
    const fn=window[name];if(!fn)continue;
    window[name]=function(...args){const t=performance.now();try{return fn.apply(this,args)}finally{const metric=audit.functions[name]??={ms:0,calls:0,max:0};const ms=performance.now()-t;metric.ms+=ms;metric.calls++;metric.max=Math.max(metric.max,ms);if(name==='renderRecordsForGeneration'&&!audit.mapReady){audit.mapReady=performance.now();requestAnimationFrame(()=>requestAnimationFrame(()=>audit.mapPaint=performance.now()))}}};
   }
  });
 });
 const page=await context.newPage(); const report={browser:browser.version(),runs:[]};
 for(const temperature of ['cold','warm','warm']){
  await page.goto(process.env.AUDIT_URL || 'http://127.0.0.1:8873/'+(process.argv[2]||'baseline')+'/web/');
  await page.waitForFunction(()=>window.audit?.mapPaint&&document.querySelector('.results-list.is-masonry-ready'));
  await page.waitForTimeout(500);
  const initial=await page.evaluate(()=>({audit:structuredClone(audit),resources:performance.getEntriesByType('resource').filter(e=>/\.json/.test(e.name)).map(e=>({name:e.name.split('/').pop(),start:e.startTime,ms:e.duration,protocol:e.nextHopProtocol,transfer:e.transferSize,encoded:e.encodedBodySize,decoded:e.decodedBodySize})),memory:performance.memory?{used:performance.memory.usedJSHeapSize,total:performance.memory.totalJSHeapSize}:null,count:currentFilteredPaperRecords.length,markers:visibleMarkerEntries.length}));
  const interact=async(fn)=>page.evaluate(async(fn)=>{const t=performance.now();eval(fn);await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return performance.now()-t},fn);
  const filterMs=await interact("taskFilter.options[2].selected=true;taskFilter.dispatchEvent(new Event('change',{bubbles:true}))");
  await page.waitForTimeout(350);
  const searchMs=await interact("keywordFilter.value='Tsinghua';keywordFilter.dispatchEvent(new Event('input',{bubbles:true}))");
  await page.waitForTimeout(500);
  const searchSettled=await page.evaluate(()=>({functions:audit.functions,searchCount:currentFilteredPaperRecords.length,longTasks:audit.longTasks,errors:audit.errors}));
  report.runs.push({temperature,initial,filterMs,searchInputToTwoFramesMs:searchMs,searchSettled});
 }
 fs.writeFileSync(out+'/'+(process.argv[2]||'baseline')+'-performance.json',JSON.stringify(report,null,2));
 console.log(JSON.stringify(report,null,2));await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
